// Hydra video synth skeleton -- globals only, no imports, one chain ending in .out()
osc(12, 0.08, 1.4)
  .rotate(noise(2))
  .scale(noise(2, 0.3))
  .kaleid(gradient(1.5))
  .repeat(voronoi(5))
  .color(noise(3, 0.2), 0.2, 1.0)
  .modulate(noise(3, 0.2), 0.15)
  .add(shape(4).rotate(0.5), 0.3)
  .diff(voronoi(5), noise(3, 0.2))
  .out()